export type LogLevel = 'debug' | 'info' | 'warn' | 'error'

export interface Config {
  port: number
  databaseUrl: string
  logLevel: LogLevel
  enableMetrics: boolean
  /** Origins allowed to call the billing API from a browser (CORS). */
  allowedOrigins: string[]
  requestTimeoutMs: number
