/** One entry per variable we read. Used to explain failures without echoing values. */
const RULES = {
  PORT: 'must be an integer from 1 to 65535',
  DATABASE_URL: 'is required and must be a postgres:// or postgresql:// URL',
  LOG_LEVEL: 'must be one of debug, info, warn, error',
  ENABLE_METRICS: 'must be one of true, false, 1, 0, yes, no (any letter case)',
  ALLOWED_ORIGINS: 'must be a comma-separated list of https origins, e.g. https://app.example.com',
  REQUEST_TIMEOUT_MS: 'must be a positive integer',
} as const

type EnvName = keyof typeof RULES

