export function loadConfig(env: Record<string, string | undefined> = process.env): Config {
  const result = envSchema.safeParse(env)
  if (!result.success) {
    const failed = new Set<string>()
    for (const issue of result.error.issues) {
      if (typeof issue.path[0] === 'string') failed.add(issue.path[0])
    }
    const lines = (Object.keys(RULES) as EnvName[])
      .filter((name) => failed.has(name))
      .map((name) => `  - ${name} ${RULES[name]}`)
    throw new Error(`Invalid environment configuration:\n${lines.join('\n')}`)
  }

  const data = result.data
  return {
    port: data.PORT,
    databaseUrl: data.DATABASE_URL,
    logLevel: data.LOG_LEVEL,
    enableMetrics: data.ENABLE_METRICS,
    allowedOrigins: [...data.ALLOWED_ORIGINS],
    requestTimeoutMs: data.REQUEST_TIMEOUT_MS,
  }
}

